const userMessage = $json.body.message || '';
let response = {};

if (userMessage.includes('intent_avocados') || userMessage.toLowerCase().includes('aguacate')) {
  response = {
    timeline: [
      { type: 'text', content: '¡Los Hass están cremosos hoy! Aquí tienes:' },
      { type: 'products', items: [{ id: 'hass-1', name: 'Aguacate Hass Premium', price: 5500, image: 'https://tus-aguacates.vercel.app/images/hass.jpg' }] },
      { type: 'options', options: [{ label: '🛒 Comprar', value: 'add_hass' }] }
    ]
  };
} else {
  response = {
    timeline: [
      { type: 'text', content: 'Entendido. Como Mayordomo Inteligente, estoy buscando eso para ti...' },
      { type: 'text', content: '(Nota: Para que yo piense de verdad, debes configurar mi nodo OpenAI en n8n)' }
    ]
  };
}

return response;
